public class ProductsController : Controller
{
    // All authenticated users
    public IActionResult List() => View();

    // Only admins can create products
    [Authorize(Roles = "Admin")]
    public IActionResult Create() => View();

    // Admins and managers can edit
    [Authorize(Roles = "Admin,Manager")]
    public IActionResult Edit(int id) => View();
}

// Deny access to a specific role
[Authorize(Roles = "Admin", Policy = "RequireEmailVerified")]
public IActionResult AdminSettings() => View();

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("RequireAdmin", policy =>
        policy.RequireRole("Admin"));

    options.AddPolicy("RequireManagerOrAdmin", policy =>
        policy.RequireRole("Admin", "Manager"));

    options.AddPolicy("RequireSeniorManagement", policy =>
        policy.RequireRole("Admin")
               .RequireClaim("Department", "Executive"));
});

// Apply the policy in a controller
[Authorize(Policy = "RequireAdmin")]
public IActionResult SystemSettings() => View();

[Authorize(Policy = "RequireSeniorManagement")]
public IActionResult BoardReports() => View();

public IActionResult Index()
{
    if (User.IsInRole("Admin"))
    {
        ViewBag.ShowAdminPanel = true;
    }

    var isManager = User.IsInRole("Manager");
    ViewBag.ShowManagerTools = isManager;

    return View();
}

